import{_ as n,C as r,o as t,c as s,a3 as o,b as l,w as a,a as c,E as d,a2 as p}from"./chunks/framework.f9NGPe18.js";const y=JSON.parse('{"title":"Overview","description":"Understand the architecture, components, and design philosophy of Logician.","frontmatter":{"title":"Overview","description":"Understand the architecture, components, and design philosophy of Logician."},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),h={name:"overview.md"};function g(u,e,m,A,b,f){const i=r("Mermaid");return t(),s("div",null,[e[1]||(e[1]=o('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>Logician is a local-first coding agent built on a modular architecture. This page explains how the pieces fit together.</p><h2 id="design-philosophy" tabindex="-1">Design philosophy <a class="header-anchor" href="#design-philosophy" aria-label="Permalink to &quot;Design philosophy&quot;">​</a></h2><ul><li><strong>No cloud dependency</strong> — everything runs locally. The LLM is called via an OpenAI-compatible API, but all reasoning, sessions, and tool execution happen on your machine.</li><li><strong>Streaming-first</strong> — every token, tool call, and reasoning step is visible in real time. No black-box prompts.</li><li><strong>Safe by default</strong> — edits use strict exact-text matching with CRLF/BOM preservation. Permission modes control how aggressively the agent acts.</li><li><strong>Extensible</strong> — skills (<code>SKILL.md</code> files), plugins, and MCP servers extend capabilities without code changes.</li></ul><h2 id="component-architecture" tabindex="-1">Component architecture <a class="header-anchor" href="#component-architecture" aria-label="Permalink to &quot;Component architecture&quot;">​</a></h2>',5)),(t(),l(p,null,{default:a(()=>[d(i,{id:"mermaid-34",class:"mermaid",graph:"graph%20TB%0A%20%20subgraph%20TUI%0A%20%20%20%20A%5BTerminal%20UI%5D%0A%20%20end%0A%20%20subgraph%20Agent%0A%20%20%20%20B%5BCoding%20Agent%5D%0A%20%20%20%20C%5BAgent%20Core%5D%0A%20%20end%0A%20%20subgraph%20Capabilities%0A%20%20%20%20D%5BReasoners%5D%0A%20%20%20%20E%5BSubagents%5D%0A%20%20%20%20F%5BTodo%20%26%20Task%20Mgmt%5D%0A%20%20%20%20G%5BEOH%20Engine%5D%0A%20%20end%0A%20%20subgraph%20Storage%0A%20%20%20%20H%5BSession%20DB%5D%0A%20%20%20%20I%5BMemory%20Store%5D%0A%20%20end%0A%20%20subgraph%20External%0A%20%20%20%20J%5BLLM%20Backend%5D%0A%20%20%20%20K%5BMCP%20Servers%5D%0A%20%20end%0A%0A%20%20A%20--%3E%20B%0A%20%20B%20--%3E%20C%0A%20%20C%20--%3E%20J%0A%20%20B%20--%3E%20D%0A%20%20B%20--%3E%20E%0A%20%20B%20--%3E%20F%0A%20%20B%20--%3E%20G%0A%20%20B%20--%3E%20H%0A%20%20B%20--%3E%20I%0A%20%20B%20--%3E%20K%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="core-packages" tabindex="-1">Core packages <a class="header-anchor" href="#core-packages" aria-label="Permalink to &quot;Core packages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Package</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>agent-core</code></td><td>Agent loop, backend, configuration, compaction, hooks, tools</td></tr><tr><td><code>coding-agent</code></td><td>System prompt, skills loading, sessions, trust model, TUI utilities</td></tr><tr><td><code>agent-capabilities</code></td><td>Reasoners (ToT, SSR, Reflexion), subagents, todo management, EOH</td></tr><tr><td><code>tui</code></td><td>Terminal UI components, engine, layers, state management</td></tr></tbody></table><h3 id="key-concepts" tabindex="-1">Key concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key concepts&quot;">​</a></h3><ul><li><strong>Agent loop</strong> — the core cycle: receive input → build system prompt → call LLM → parse response → execute tools → repeat.</li><li><strong>Skills</strong> — <code>SKILL.md</code> files that inject specialized instructions into the system prompt when triggered.</li><li><strong>Hooks</strong> — lifecycle callbacks (before/after tool calls, before/after LLM requests, etc.) for plugins.</li><li><strong>Sessions</strong> — persistent conversation history stored in SQLite, with support for bookmarks, branching, and compaction.</li><li><strong>Trust model</strong> — permission modes (<code>acceptAll</code>, <code>acceptEdits</code>, <code>ask</code>, <code>plan</code>) control agent behavior.</li></ul><h2 id="why-local-first" tabindex="-1">Why local-first? <a class="header-anchor" href="#why-local-first" aria-label="Permalink to &quot;Why local-first?&quot;">​</a></h2><p>Cloud-dependent agents have a single point of failure and leak your code to third parties. Logician runs entirely on your machine — the LLM call is the only external network request, and even that goes to an endpoint you configure.</p><p>This means:</p><ul><li>Your code never leaves your machine</li><li>No API key stored in a cloud service</li><li>Works offline (except for LLM calls)</li><li>Full control over data retention and session history</li></ul>',8))])}const k=n(h,[["render",g]]);export{y as __pageData,k as default};
